CREATE DEFINER=`root`@`localhost` PROCEDURE `Check_App_Version`(
    IN p_Version VARCHAR(45)
)
BEGIN
    -- Check if the provided version matches any version in the table and return 1 or 0
    SELECT
        CASE
            WHEN EXISTS (
                SELECT 1
                FROM mobile_version
                WHERE Version = p_Version
            ) THEN 1
            ELSE 0
        END AS IsEqual;
END ;;
