CREATE DEFINER=`root`@`localhost` PROCEDURE `Delete_Course_Content`(IN Content_Id_ INT)
BEGIN
    DECLARE affectedRows INT DEFAULT 0;
    DECLARE examId_ INT DEFAULT NULL;

    -- Get Exam_ID before deletion
    SELECT Exam_ID INTO examId_ FROM course_content WHERE Content_ID = Content_Id_ LIMIT 1;

    -- Clean up child tables that reference Content_ID
    DELETE FROM video_attendance WHERE Content_ID = Content_Id_;
    DELETE FROM unlocked_exam WHERE Content_ID = Content_Id_;
    DELETE FROM student_exam WHERE Content_Id = Content_Id_;

    -- Delete from course_content table
    DELETE FROM course_content WHERE Content_ID = Content_Id_;
    SET affectedRows = affectedRows + ROW_COUNT();

    -- Also delete associated exam if exists
    IF examId_ IS NOT NULL AND examId_ > 0 THEN
        DELETE FROM question WHERE Exam_ID = examId_;
        DELETE FROM student_exam WHERE Exam_Id = examId_;
        DELETE FROM exam WHERE Exam_ID = examId_;
    END IF;

    -- Return the total number of affected rows
    SELECT affectedRows AS TotalAffectedRows;
END ;;
DELIMITER ;
