CREATE DEFINER=`root`@`localhost` PROCEDURE `GetCallsAndChats`(
    IN p_type VARCHAR(20),
    IN p_sender VARCHAR(20),
    IN p_teacher_id INT,
    IN p_student_id INT
)
BEGIN
    IF p_type = 'call' THEN
        IF p_sender = 'teacher' THEN
            SELECT
                id,
                teacher_id,
                student_id,
                call_start,
                call_end,
                call_duration,
                call_type
            FROM call_history
            WHERE teacher_id = p_teacher_id;
        ELSEIF p_sender = 'student' THEN
            SELECT
                id,
                teacher_id,
                student_id,
                call_start,
                call_end,
                call_duration,
                call_type
            FROM call_history
            WHERE student_id = p_student_id;
        END IF;
    ELSEIF p_type = 'chat' THEN
        IF p_sender = 'teacher' THEN
            SELECT
                chat_id,
                teacher_id,
                student_id,
                message,
                timestamp
            FROM student_teacher_chat
            WHERE teacher_id = p_teacher_id;
        ELSEIF p_sender = 'student' THEN
            SELECT
                chat_id,
                teacher_id,
                student_id,
                message,
                timestamp
            FROM student_teacher_chat
            WHERE student_id = p_student_id;
        END IF;
    END IF;
END ;;
DELIMITER ;
