CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Calls_And_Chats_List`(
    IN p_type VARCHAR(20),
    IN p_sender VARCHAR(20),
    IN p_teacher_id INT,
    IN p_student_id INT
)
BEGIN
    IF p_type = 'call' THEN
			IF p_sender = 'teacher' THEN
				SELECT
					call_history.*,
					s.Profile_Photo_Path,
					s.First_Name,
					s.Delete_Status
				FROM call_history
				INNER JOIN student s ON s.Student_ID = call_history.student_id
				WHERE teacher_id = p_teacher_id AND Is_Finished = 1
				ORDER BY id DESC
				LIMIT 20;
			ELSEIF p_sender = 'student' THEN
				SELECT
					call_history.*,
					u.User_ID,
					u.First_Name,
					u.Profile_Photo_Path,
					u.Delete_Status
				FROM call_history
				INNER JOIN users u ON u.User_ID = call_history.teacher_id
				WHERE student_id = p_student_id AND Is_Finished = 1
				ORDER BY id DESC
				LIMIT 20;
			END IF;


		ELSEIF p_type = 'chat' THEN
    IF p_sender = 'teacher' THEN
			  SELECT 
			stc.student_id,
			s.First_Name,
			s.Last_Name,
			s.Profile_Photo_Path,
			MAX(stc.message) AS message,  -- Use MAX or another aggregate function
			s.Delete_Status,
			MAX(stc.File_Path) AS File_Path,  -- Aggregate the file path
			MAX(stc.timestamp) AS timestamp,  -- Aggregate the timestamp
			(SELECT COUNT(*) 
			 FROM student_teacher_chat 
			 WHERE teacher_id = p_teacher_id 
			   AND student_id = stc.student_id 
			   AND Is_Student_Sent = 1 
			   AND is_read = 0) AS unread_count
		FROM student_teacher_chat stc
		INNER JOIN student s ON s.Student_ID = stc.student_id
		INNER JOIN (
			SELECT student_id, MAX(timestamp) AS max_timestamp
			FROM student_teacher_chat
			WHERE teacher_id = p_teacher_id
			GROUP BY student_id 
		) latest ON stc.student_id = latest.student_id 
				  AND stc.timestamp = latest.max_timestamp
		WHERE stc.teacher_id = p_teacher_id
		GROUP BY 
			stc.student_id, 
			s.First_Name, 
			s.Last_Name, 
			s.Profile_Photo_Path, 
			s.Delete_Status  
		ORDER BY MAX(stc.timestamp) DESC;  

    ELSEIF p_sender = 'student' THEN
				 SELECT
				stc.teacher_id,
				u.First_Name,
				u.Last_Name,
				u.Delete_Status,
				u.Profile_Photo_Path,
				MAX(stc.message) AS message,  -- Aggregate message
				MAX(stc.File_Path) AS File_Path,  -- Aggregate File_Path
				MAX(stc.timestamp) AS timestamp,  -- Aggregate timestamp
				(SELECT COUNT(*) 
				 FROM student_teacher_chat 
				 WHERE student_id = p_student_id 
				   AND teacher_id = stc.teacher_id 
				   AND Is_Student_Sent = 0 
				   AND is_read = 0) AS unread_count
			FROM student_teacher_chat stc
			INNER JOIN users u ON u.User_ID = stc.teacher_id
			INNER JOIN (
				SELECT teacher_id, MAX(timestamp) AS max_timestamp
				FROM student_teacher_chat
				WHERE student_id = p_student_id
				GROUP BY teacher_id
			) latest ON stc.teacher_id = latest.teacher_id AND stc.timestamp = latest.max_timestamp
			WHERE stc.student_id = p_student_id
			GROUP BY 
				stc.teacher_id, 
				u.First_Name, 
				u.Last_Name, 
				u.Delete_Status, 
				u.Profile_Photo_Path  -- Include all non-aggregated fields here
			ORDER BY MAX(stc.timestamp) DESC;  -- Order by the maximum timestamp

    END IF;
END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
