DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_ExamDetails_By_StudentId`(
    IN student_Id_ INT,
    IN exam_Id_ INT
)
BEGIN
    SELECT
        e.Main_Question,
        cc.Content_Name,
        e.file_name,
        e.file_type,
        e.Passing_Score,
        e.Time_Limit,
        e.Total_Questions,
        (
            SELECT
                JSON_ARRAYAGG(
                    JSON_OBJECT(
                        'Question_ID', q.Question_ID,
                        'Answer_Media_Name', q.Answer_Media_Name,
                        'questionText', q.Question_Text,
                        'answerOptions', q.Answer_Options,
                        'correctAnswer', q.Correct_Answer,
                        'Submitted_Answer', (
                            SELECT a.Submitted_Answer
                            FROM student_exam_answer a
                            WHERE
                                a.StudentExam_ID = (
                                    SELECT StudentExam_ID
                                    FROM student_exam
                                    WHERE Student_ID = student_Id_
                                        AND Exam_ID = exam_Id_
                                )
                                AND a.Question_ID = q.Question_ID
                            LIMIT 1
                        )
                    )
                )
            FROM
                question q
            WHERE
                q.Exam_ID = exam_Id_
                AND q.Delete_Status = 0
        ) AS questions,
        IF(
            (
                SELECT COUNT(*)
                FROM student_exam
                WHERE Student_ID = student_Id_
                    AND Exam_ID = exam_Id_
            ) > 0,
            TRUE,
            FALSE
        ) AS Attended_Exam
    FROM
        exam e
        JOIN course_content cc ON e.Exam_ID = cc.Exam_ID
    WHERE
        e.Exam_ID = exam_Id_;
END ;;
DELIMITER ;
