/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `Get_Exam_Results_By_Student`(
    IN p_student_id INT,
    IN p_course_id INT
)
BEGIN
    SELECT 
        erm.exam_result_master_id,
        erm.student_id,
        erm.course_id,
        erm.course_exam_id,
        erm.exam_data_id,
        erm.total_mark,
        erm.pass_mark,
        erm.obtained_mark,
        erm.created_at,
        erm.updated_at,
        s.First_Name,
        s.Last_Name,
        c.Course_Name,
        ed.exam_name,
        CASE 
            WHEN erm.obtained_mark >= erm.pass_mark THEN 'Pass'
            ELSE 'Fail'
        END AS result_status,
        ROUND((erm.obtained_mark / erm.total_mark) * 100, 2) AS percentage
    FROM exam_result_master erm
    INNER JOIN student s ON erm.student_id = s.Student_ID
    INNER JOIN course c ON erm.course_id = c.Course_ID
    INNER JOIN exam_data ed ON erm.exam_data_id = ed.exam_data_id
    WHERE (p_student_id = 0 OR erm.student_id = p_student_id)
    AND (p_course_id IS NULL OR p_course_id = 0 OR erm.course_id = p_course_id)
    ORDER BY erm.created_at DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
