/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `Get_Faculty_Batch_Students`(
    IN teacher_id_ INT
)
BEGIN
    SELECT DISTINCT
        cb.Batch_ID,
        cb.Batch_Name,
        cb.Start_Date,
        cb.End_Date,
        c.Course_ID,
        c.Course_Name,
        sc.Student_ID,
        s.First_Name,
        s.Last_Name,
        s.Email,
        s.Phone_Number,
        s.Profile_Photo_Path,
        sc.Enrollment_Date,
        sc.Expiry_Date,
        sc.Payment_Status
    FROM 
        course_teacher ct
    INNER JOIN course c 
        ON c.Course_ID = ct.Course_ID
    INNER JOIN teacher_time_slot tts
        ON tts.CourseTeacher_ID = ct.CourseTeacher_ID
    INNER JOIN course_batch cb 
        ON cb.Course_ID = ct.Course_ID
    INNER JOIN student_course sc 
        ON sc.Batch_ID = cb.Batch_ID 
        AND sc.Course_ID = ct.Course_ID
        AND sc.Slot_Id = tts.Slot_Id
    INNER JOIN student s 
        ON s.Student_ID = sc.Student_ID
    WHERE 
        ct.Teacher_ID = teacher_id_
        AND ct.Delete_Status = FALSE
        AND tts.Delete_Status = FALSE
        AND cb.Delete_Status = FALSE
        AND c.Delete_Status = FALSE
        AND sc.Delete_Status = FALSE
        AND s.Delete_Status = FALSE
        AND sc.Expiry_Date > CURDATE()
    ORDER BY 
        cb.Batch_Name, s.First_Name, s.Last_Name;
END ;;
