DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `Get_MonthlyAttendanceAvg`()
BEGIN
    SELECT 
        month_name,
        IFNULL(AVG(attendance_rate), 0) as average_rate
    FROM (
        SELECT 
            DATE_FORMAT(va.Watched_Date, '%M') as month_name,
            MONTH(va.Watched_Date) as month_num,
            YEAR(va.Watched_Date) as year_num,
            b.Batch_ID,
            (COUNT(DISTINCT va.Student_ID) / NULLIF(COUNT(DISTINCT sc.Student_ID), 0)) * 100 as attendance_rate
        FROM video_attendance va
        JOIN student_course sc ON va.Student_ID = sc.Student_ID
        JOIN course_batch b ON sc.Batch_ID = b.Batch_ID
        WHERE va.Watched_Date >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH)
          AND va.Delete_Status = 0
          AND sc.Delete_Status = 0
          AND b.Delete_Status = 0
        GROUP BY DATE(va.Watched_Date), b.Batch_ID
    ) daily_batch_rates
    GROUP BY year_num, month_num, month_name
    ORDER BY year_num, month_num;
END ;;
DELIMITER ;
