CREATE DEFINER=`root`@`localhost` PROCEDURE `Get_Sections_By_Course`(
    IN p_course_id INT
)
BEGIN
    SELECT 
        s.Section_ID,
        s.ExamType_ID,
        s.Section_Name,
        s.Delete_Status
    FROM course_section cs
    INNER JOIN section s ON cs.Section_ID = s.Section_ID
    WHERE cs.Course_ID = p_course_id
    ORDER BY s.Section_ID;
END ;;
