    IN p_Student_ID INT,
    IN p_Course_ID INT
)
BEGIN
    SELECT 
       s.*,cc.Content_Name
    FROM 
        student_exam s
        left join course_content cc on cc.Exam_ID =s.Exam_ID
    WHERE 
        Student_ID = p_Student_ID AND s.Course_ID = p_Course_ID AND s.Delete_Status = 0; -- Assuming 0 means not deleted
