CREATE DEFINER=`root`@`%` PROCEDURE `Save_AppPoster`(
    IN p_id INT,
    IN p_title VARCHAR(255),
    IN p_image_path VARCHAR(1000),
    IN p_link_url VARCHAR(1000),
    IN p_is_active TINYINT
)
BEGIN
    IF p_id = 0 THEN
        INSERT INTO app_posters (title, image_path, link_url, is_active)
        VALUES (p_title, p_image_path, p_link_url, p_is_active);
        SELECT LAST_INSERT_ID() AS id;
    ELSE
        UPDATE app_posters
        SET title = p_title,
            image_path = p_image_path,
            link_url = p_link_url,
            is_active = p_is_active
        WHERE id = p_id;
        SELECT p_id AS id;
    END IF;
END ;;
DELIMITER ;
