CREATE DEFINER=`root`@`%` PROCEDURE `Save_VideoAttendance`(
    IN p_Student_ID INT,
    IN p_Course_ID INT,
    IN p_Content_ID INT
)
BEGIN
    DECLARE v_ExistingID INT;

    -- Check if attendance already exists for this student and content
    SELECT VideoAttendance_ID INTO v_ExistingID
    FROM video_attendance
    WHERE Student_ID = p_Student_ID 
      AND Content_ID = p_Content_ID
      AND Delete_Status = 0
    LIMIT 1;

    IF v_ExistingID IS NOT NULL THEN
        -- Update the update time to track last view
        UPDATE video_attendance
        SET Update_Time = CURRENT_TIMESTAMP
        WHERE VideoAttendance_ID = v_ExistingID;
        
        SELECT v_ExistingID AS VideoAttendance_ID;
    ELSE
        -- Insert new record
        INSERT INTO video_attendance (Student_ID, Course_ID, Content_ID)
        VALUES (p_Student_ID, p_Course_ID, p_Content_ID);
        
        SELECT LAST_INSERT_ID() AS VideoAttendance_ID;
    END IF;
END ;;
DELIMITER ;
