CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_CourseExam_Manage`(
    IN p_action VARCHAR(50),
    IN p_course_exam_id INT,
    IN p_exam_data_id INT,
    IN p_Course_ID INT,
    IN p_duration INT,
    IN p_questions INT,
    IN p_passcount INT,
    IN p_Day INT
)
BEGIN
    IF p_action = 'INSERT' THEN
        INSERT INTO course_exam 
        (exam_data_id, Course_ID, duration, questions, passcount, Day)
        VALUES 
        (p_exam_data_id, p_Course_ID, p_duration, p_questions, p_passcount, p_Day);
        
    ELSEIF p_action = 'UPDATE' THEN
        UPDATE course_exam
        SET exam_data_id = p_exam_data_id,
            Course_ID = p_Course_ID,
            duration = p_duration,
            questions = p_questions,
            passcount = p_passcount,
            Day = p_Day
        WHERE course_exam_id = p_course_exam_id;
        
    ELSEIF p_action = 'DELETE' THEN
        DELETE FROM course_exam WHERE course_exam_id = p_course_exam_id;
    END IF;
END ;;
