CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_ExamData_Manage`(
    IN p_action VARCHAR(20),
    IN p_exam_data_id INT,
    IN p_exam_name VARCHAR(255)
)
BEGIN
    IF p_action = 'INSERT' THEN
        INSERT INTO exam_data (exam_name) VALUES (p_exam_name);
        SELECT LAST_INSERT_ID() AS id;
    ELSEIF p_action = 'UPDATE' THEN
        UPDATE exam_data SET exam_name = p_exam_name WHERE exam_data_id = p_exam_data_id;
    ELSEIF p_action = 'DELETE' THEN
        DELETE FROM exam_data WHERE exam_data_id = p_exam_data_id;
    ELSEIF p_action = 'SELECT' THEN
        IF p_exam_data_id IS NOT NULL THEN
            SELECT * FROM exam_data WHERE exam_data_id = p_exam_data_id;
        ELSE
            SELECT * FROM exam_data;
        END IF;
    END IF;
END ;;
