BEGIN
  DECLARE cart_id_ INT;

  SELECT id INTO cart_id_
  FROM carts
  WHERE user_id = user_id_ limit 1;

  IF cart_id_ IS NOT NULL THEN
    UPDATE cart_items
    SET quantity = new_quantity_
